import type { ReactNode } from "react";

/**
 * Shared primitives. Every one that holds a backend-authored string carries
 * `min-w-0` / `wrap-any`, because ERC details, file paths and net names have no
 * length bound and a flex or grid child defaults to `min-width: auto`.
 */

export function Panel({
  eyebrow,
  title,
  aside,
  children,
  className = "",
}: {
  eyebrow?: string;
  title?: string;
  aside?: ReactNode;
  children: ReactNode;
  className?: string;
}) {
  const hasHeader = Boolean(eyebrow || title || aside);
  return (
    <section className={`panel ${className}`}>
      {hasHeader && (
        <header className="flex flex-wrap items-end justify-between gap-x-4 gap-y-3 border-b border-rule px-4 py-3 sm:px-5">
          <div className="min-w-0">
            {eyebrow && <p className="eyebrow">{eyebrow}</p>}
            {title && (
              <h2 className="mt-1.5 text-[0.9375rem] font-semibold leading-tight tracking-[-0.012em] text-ink">
                {title}
              </h2>
            )}
          </div>
          {/* Controls keep their own `shrink-0`; a text aside has to be able to
              wrap instead of pushing the header wider than the panel. */}
          {aside && <div className="min-w-0 max-w-full">{aside}</div>}
        </header>
      )}
      <div className="px-4 py-4 sm:px-5">{children}</div>
    </section>
  );
}

/** Two-state switch used for schematic/pcb and words/fields. */
export function Segmented<T extends string>({
  options,
  value,
  onChange,
  disabled,
  label,
}: {
  options: { value: T; label: string; disabled?: boolean }[];
  value: T;
  onChange: (next: T) => void;
  disabled?: boolean;
  label: string;
}) {
  return (
    <div
      role="group"
      aria-label={label}
      className="inline-flex shrink-0 gap-0.5 rounded border border-rule bg-paper p-0.5"
    >
      {options.map((option) => (
        <button
          key={option.value}
          type="button"
          className="seg"
          aria-pressed={option.value === value}
          disabled={disabled || option.disabled}
          onClick={() => onChange(option.value)}
        >
          {option.label}
        </button>
      ))}
    </div>
  );
}

type Tone = "neutral" | "wire" | "brick" | "copper";

const NOTICE_TONE: Record<Tone, string> = {
  neutral: "border-rule bg-paper text-muted",
  wire: "border-wire/30 bg-wire-soft text-ink",
  brick: "border-brick/35 bg-brick-soft text-ink",
  copper: "border-copper-line/45 bg-copper-soft text-ink",
};

export function Notice({
  tone = "neutral",
  title,
  children,
}: {
  tone?: Tone;
  title?: string;
  children?: ReactNode;
}) {
  return (
    <div className={`rounded border p-3 text-[0.8125rem] leading-snug ${NOTICE_TONE[tone]}`}>
      {title && <p className="eyebrow mb-1.5 text-ink">{title}</p>}
      <div className="min-w-0 wrap-any">{children}</div>
    </div>
  );
}

/** Mono data token: designators, net names, file paths, check names. */
export function Chip({
  children,
  tone = "neutral",
  title,
}: {
  children: ReactNode;
  tone?: Tone;
  title?: string;
}) {
  const tones: Record<Tone, string> = {
    neutral: "",
    wire: "border-wire/35 bg-wire-soft text-wire",
    brick: "border-brick/35 bg-brick-soft text-brick",
    copper: "border-copper-line/45 bg-copper-soft text-copper",
  };
  return (
    <span className={`chip ${tones[tone]}`} title={title}>
      {children}
    </span>
  );
}

export function StatusDot({ tone }: { tone: Tone }) {
  const tones: Record<Tone, string> = {
    neutral: "bg-rule",
    wire: "bg-wire",
    brick: "bg-brick",
    copper: "bg-copper-line",
  };
  return <span aria-hidden className={`h-1.5 w-1.5 shrink-0 rounded-full ${tones[tone]}`} />;
}

/** Label over value, stacked. The value may be a long machine string. */
export function DataCell({ label, value, mono = true }: { label: string; value: string; mono?: boolean }) {
  return (
    <div className="min-w-0">
      <dt className="eyebrow">{label}</dt>
      <dd
        className={`mt-1 min-w-0 wrap-any text-[0.8125rem] leading-snug text-ink ${mono ? "font-mono" : ""}`}
      >
        {value}
      </dd>
    </div>
  );
}

export function Bullets({ title, items, tone = "neutral" }: { title: string; items: string[]; tone?: Tone }) {
  if (items.length === 0) return null;
  const markers: Record<Tone, string> = {
    neutral: "before:bg-rule",
    wire: "before:bg-wire",
    brick: "before:bg-brick",
    copper: "before:bg-copper-line",
  };
  return (
    <div className="mt-4 min-w-0">
      <h3 className="eyebrow">{title}</h3>
      <ul className="mt-2 space-y-1.5">
        {items.map((item) => (
          <li
            key={item}
            className={`relative min-w-0 wrap-any pl-4 text-[0.8125rem] leading-snug text-muted before:absolute before:left-0 before:top-[0.5em] before:h-1 before:w-1 before:rounded-full ${markers[tone]}`}
          >
            {item}
          </li>
        ))}
      </ul>
    </div>
  );
}

########## globals.css ##########
@tailwind base;
@tailwind components;
@tailwind utilities;

/*
 * Palette: KiCAD's canvas colours — wire teal, component red-brown, board
 * copper — on cool drafting paper. Deliberately light-only: kicad-cli renders
 * the schematic on white, so the UI is the paper around that render rather
 * than a dark frame fighting it.
 */
:root {
  --ink: #171c1a;
  --paper: #edf0ee;
  --sheet: #ffffff;
  --rule: #cbd2ce;
  --muted: #5a6763;

  --wire: #0b7a69;
  --wire-soft: #e1efec;
  --brick: #a33327;
  --brick-soft: #f9e9e6;
  --copper: #8a5e1b;
  --copper-line: #c08a34;
  --copper-soft: #f9f0dc;

  --background: var(--paper);
  --foreground: var(--ink);
}

@layer base {
  html {
    -webkit-text-size-adjust: 100%;
  }

  body {
    background-color: var(--paper);
    color: var(--ink);
    font-family: var(--font-archivo), ui-sans-serif, system-ui, sans-serif;
    /* Backend-authored strings (paths, net names, ERC details) are arbitrarily
       long; nothing may push the page sideways. */
    overflow-wrap: break-word;
  }

  :focus-visible {
    outline: 2px solid var(--wire);
    outline-offset: 2px;
    border-radius: 2px;
  }

  ::selection {
    background-color: var(--wire-soft);
  }

  /* Native controls follow the palette instead of the OS blue. */
  input,
  textarea,
  select,
  button {
    accent-color: var(--wire);
  }
}

@layer components {
  /* Small uppercase mono label. The utility voice: it names things, never explains. */
  .eyebrow {
    font-family: var(--font-plex-mono), ui-monospace, monospace;
    font-size: 0.625rem;
    font-weight: 500;
    line-height: 1;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--muted);
    /* Some eyebrows carry backend strings (an action type, a check name). */
    overflow-wrap: anywhere;
  }

  .panel {
    background-color: var(--sheet);
    border: 1px solid var(--rule);
    border-radius: 3px;
  }

  .btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    flex-shrink: 0;
    border-radius: 3px;
    border: 1px solid transparent;
    padding: 0.5rem 0.875rem;
    font-size: 0.8125rem;
    font-weight: 600;
    letter-spacing: -0.005em;
    line-height: 1.15;
    background-color: var(--wire);
    color: #fff;
    transition: background-color 140ms ease, border-color 140ms ease, color 140ms ease;
  }

  .btn:hover:not(:disabled) {
    background-color: #095f52;
  }

  .btn:disabled {
    background-color: #dfe4e1;
    border-color: var(--rule);
    color: #8c9995;
    cursor: not-allowed;
  }

  /* Secondary: hairline outline, ink text. Kept as the old class name too so
     no call site silently loses its styling. */
  .btn-ghost,
  .btn-secondary {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    flex-shrink: 0;
    border-radius: 3px;
    border: 1px solid var(--rule);
    padding: 0.5rem 0.875rem;
    font-size: 0.8125rem;
    font-weight: 500;
    line-height: 1.15;
    background-color: transparent;
    color: var(--ink);
    transition: background-color 140ms ease, border-color 140ms ease, color 140ms ease;
  }

  .btn-ghost:hover:not(:disabled),
  .btn-secondary:hover:not(:disabled) {
    border-color: var(--wire);
    color: var(--wire);
    background-color: var(--wire-soft);
  }

  .btn-ghost:disabled,
  .btn-secondary:disabled {
    color: #8c9995;
    cursor: not-allowed;
  }

  /* Segmented control: the two-state switches (schematic/pcb, words/fields). */
  .seg {
    font-family: var(--font-plex-mono), ui-monospace, monospace;
    font-size: 0.6875rem;
    font-weight: 500;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding: 0.375rem 0.6875rem;
    border-radius: 2px;
    color: var(--muted);
    transition: background-color 140ms ease, color 140ms ease;
  }

  .seg:hover:not(:disabled):not([aria-pressed="true"]) {
    color: var(--ink);
  }

  .seg[aria-pressed="true"] {
    background-color: var(--sheet);
    color: var(--wire);
    box-shadow: 0 1px 2px rgb(23 28 26 / 0.08);
  }

  .seg:disabled {
    color: #a9b3af;
    cursor: not-allowed;
  }

  .field {
    width: 100%;
    min-width: 0;
    background-color: var(--sheet);
    border: 1px solid var(--rule);
    border-radius: 3px;
    padding: 0.4375rem 0.5625rem;
    font-size: 0.8125rem;
    color: var(--ink);
    transition: border-color 140ms ease;
  }

  .field:hover {
    border-color: #b3bcb7;
  }

  .field::placeholder {
    color: #96a19d;
  }

  /* Mono data chip: designators, net names, file paths. */
  .chip {
    display: inline-flex;
    align-items: center;
    gap: 0.375rem;
    max-width: 100%;
    min-width: 0;
    border: 1px solid var(--rule);
    border-radius: 2px;
    padding: 0.125rem 0.375rem;
    font-family: var(--font-plex-mono), ui-monospace, monospace;
    font-size: 0.6875rem;
    line-height: 1.4;
    color: var(--muted);
    overflow-wrap: anywhere;
  }
}

@layer utilities {
  /* For machine strings with no spaces to break on. */
  .wrap-any {
    overflow-wrap: anywhere;
    word-break: break-word;
  }

  /* Hairline grid, 8px pitch — the snap grid a schematic is drawn on. */
  .drafting-grid {
    background-image: linear-gradient(to right, rgb(23 28 26 / 0.045) 1px, transparent 1px),
      linear-gradient(to bottom, rgb(23 28 26 / 0.045) 1px, transparent 1px);
    background-size: 8px 8px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    /* Delays matter as much as durations here: the wire animations use
       fill-mode `both`, so a held delay would leave them invisible. */
    animation-delay: 0s !important;
    transition-delay: 0s !important;
  }
}

/* The signature: proposed connections draw themselves in, once, like routing a
   net. One orchestrated moment; everything else stays still. */
@keyframes wire-draw {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}

@keyframes junction-pop {
  0% {
    transform: scale(0);
  }
  65% {
    transform: scale(1.4);
  }
  100% {
    transform: scale(1);
  }
}

@keyframes rise-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
