import { request } from "./api";

/**
 * The ten-agent lane. Everything here mirrors the backend it describes:
 * `TEAM_AGENTS` is `app/team/registry.py`'s roster in `CANONICAL_ORDER`, and
 * `deriveFlow` reconstructs a run's shape from the append-only evidence the
 * orchestrator writes as it goes. Nothing is inferred that the backend does not
 * actually report — a stage the evidence hasn't reached yet is shown as waiting,
 * not guessed at.
 */

export const TEAM_STAGE_IDS = [
  "project_manager",
  "requirements",
  "architecture",
  "components",
  "schematic_design",
  "pcb_layout",
  "simulation",
  "verification",
  "manufacturing",
  "qa_release",
] as const;

export type TeamStageId = (typeof TEAM_STAGE_IDS)[number];

export type TeamAgent = {
  id: TeamStageId;
  /** Roster name, as the backend registry names it. */
  name: string;
  role: string;
  /** What this agent is asked to produce, in one line. */
  produces: string;
  /** The Pydantic model its output must parse into. */
  outputModel: string;
  /** Prior stage outputs it is handed — and nothing else. */
  reads: TeamStageId[];
  /** The deterministic tool that grounds its output at the gate. */
  gate: string;
  /** Whether this agent is allowed to change design files. */
  mutates: boolean;
};

export const TEAM_AGENTS: TeamAgent[] = [
  {
    id: "project_manager",
    name: "Project Manager",
    role: "Hardware project manager",
    produces: "The goal in one line, and the stage order to work in",
    outputModel: "PMPlan",
    reads: [],
    gate: "orchestrator",
    mutates: false,
  },
  {
    id: "requirements",
    name: "Requirements",
    role: "Hardware requirements engineer",
    produces: "Numbered, testable requirements with units and a source",
    outputModel: "RequirementsDoc",
    reads: ["project_manager"],
    gate: "requirements parser",
    mutates: false,
  },
  {
    id: "architecture",
    name: "System Architect",
    role: "Electronics system architect",
    produces: "Functional blocks, their connections, and which requirement each serves",
    outputModel: "Architecture",
    reads: ["requirements"],
    gate: "architecture checker",
    mutates: false,
  },
  {
    id: "components",
    name: "Component Engineer",
    role: "Component/application engineer",
    produces: "Real parts with symbols, footprints and the constraints they were checked against",
    outputModel: "ComponentSelection",
    reads: ["requirements", "architecture"],
    gate: "component checker",
    mutates: false,
  },
  {
    id: "schematic_design",
    name: "Schematic Design",
    role: "Electronics design engineer",
    produces: "Connection intents: pin to pin, pin to net, pull-ups",
    outputModel: "SchematicIntents",
    reads: ["requirements", "architecture", "components"],
    gate: "decision/state diff + KiCAD ERC",
    mutates: true,
  },
  {
    id: "pcb_layout",
    name: "PCB Layout",
    role: "PCB layout engineer",
    produces: "Footprint placements, critical nets, and what is left unrouted",
    outputModel: "LayoutProposal",
    reads: ["schematic_design"],
    gate: "board writer + KiCAD DRC",
    mutates: true,
  },
  {
    id: "simulation",
    name: "Simulation",
    role: "Circuit simulation engineer",
    produces: "Rail and current-margin tests, by closed-form arithmetic",
    outputModel: "SimulationReport",
    reads: ["schematic_design", "components"],
    gate: "simulation checker",
    mutates: false,
  },
  {
    id: "verification",
    name: "Verification",
    role: "Hardware verification engineer",
    produces: "A pass/fail/unverified outcome per requirement, with its evidence",
    outputModel: "VerificationReport",
    reads: ["schematic_design", "pcb_layout", "simulation"],
    gate: "verification checker",
    mutates: false,
  },
  {
    id: "manufacturing",
    name: "Manufacturing",
    role: "DFM/DFA engineer",
    produces: "DFM findings against the named manufacturer profile",
    outputModel: "ManufacturingReport",
    reads: ["pcb_layout", "components", "verification"],
    gate: "manufacturer checker",
    mutates: false,
  },
  {
    id: "qa_release",
    name: "QA and Release",
    role: "Hardware QA/release engineer",
    produces: "A release record: checklist, files, and a hash of what shipped",
    outputModel: "ReleaseRecord",
    reads: [
      "requirements",
      "architecture",
      "components",
      "schematic_design",
      "pcb_layout",
      "simulation",
      "verification",
      "manufacturing",
    ],
    gate: "release checker",
    mutates: false,
  },
];

export const AGENT_BY_ID: Record<TeamStageId, TeamAgent> = Object.fromEntries(
  TEAM_AGENTS.map((agent) => [agent.id, agent]),
) as Record<TeamStageId, TeamAgent>;

/** These two overlap when the backend runs with `team_parallel` on. */
export const PARALLEL_PAIR: TeamStageId[] = ["pcb_layout", "simulation"];

export type CheckFinding = {
  rule: string;
  actual: unknown;
  expected: unknown;
  kicad_object: string;
  evidence_source: string;
  severity: "error" | "warning" | "info";
};

export type TeamEvidenceRecord = {
  check: string;
  tool: string;
  project_version: string;
  timestamp: string;
  result: string;
  findings: unknown[];
  runner: string | null;
  session_url: string | null;
  status: string | null;
  acus_consumed: number;
  duration_seconds: number;
};

export type TeamAgentResult = {
  task_id: string;
  agent: string;
  status: string;
  output: unknown;
  output_artifacts: string[];
  unresolved_questions: string[];
  session_url: string | null;
  acus_consumed: number;
  duration_seconds: number;
  runner: string;
};

export type TeamRunReport = {
  run_id: string;
  request: string;
  project: {
    project_id: string;
    manufacturer_profile: Record<string, unknown>;
    design_context: {
      components: { reference: string; value: string; lib_id: string }[];
      nets: { name: string; pins: string[] }[];
      erc_baseline: { errors: number; warnings: number };
      drc_baseline: { errors: number; warnings: number } | null;
      board: { width_mm: number; height_mm: number } | null;
    } | null;
  };
  per_stage_results: Partial<Record<TeamStageId, TeamAgentResult>>;
  requirements_satisfied: number;
  requirements_total: number;
  requirements_status: string;
  erc_status: string;
  drc_status: string;
  power_tests_passed: number;
  power_tests_total: number;
  power_tests_status: string;
  manufacturing_warnings: number;
  manufacturing_status: string;
  critical_issues: number;
  open_critical_findings: CheckFinding[];
  release_status: string;
  summary: string;
};

/** Orchestrator decisions. Written once, when the run ends. */
export type TeamEvent = {
  event: string;
  from?: string;
  to?: string;
  agent?: string;
  stage?: string;
  workflow?: string[];
  findings?: CheckFinding[];
};

export type TeamRunStatus = {
  run_id: string;
  status: "running" | "completed" | "failed";
  runner: string;
  project: string;
  request?: string;
  manufacturer_profile?: string;
  session_id?: string;
  answers: string[];
  error?: string;
  events: TeamEvent[];
  report: TeamRunReport | null;
};

export const teamApi = {
  start: (body: { project: string; request: string; runner: "devin" | "stub" }) =>
    request<{ run_id: string; status: string }>("/api/team/runs", {
      method: "POST",
      body: JSON.stringify(body),
    }),
  status: (runId: string) => request<TeamRunStatus>(`/api/team/runs/${runId}`),
  evidence: (runId: string) =>
    request<{ run_id: string; status: string; records: TeamEvidenceRecord[] }>(
      `/api/team/runs/${runId}/evidence`,
    ),
  answer: (runId: string, answer: string) =>
    request<{ run_id: string; accepted: boolean; answers: string[] }>(`/api/team/runs/${runId}/answer`, {
      method: "POST",
      body: JSON.stringify({ answer }),
    }),
};

/* -------------------------------------------------------------------------- */

export type StagePhase = "waiting" | "running" | "gating" | "passed" | "failed" | "unresolved";

/** One pass of an agent through its stage. A second attempt means it was sent back. */
export type StageAttempt = {
  agent: TeamEvidenceRecord | null;
  gate: TeamEvidenceRecord | null;
  gateFindings: CheckFinding[];
};

export type StageState = {
  id: TeamStageId;
  phase: StagePhase;
  attempts: StageAttempt[];
  /** Set when the stage ended without a gate record the evidence could carry. */
  unresolvedDetail: string | null;
};

export type TraceEntry = {
  seq: number;
  stage: TeamStageId;
  kind: "agent" | "gate";
  /** Which pass through this stage, 1-based. */
  attempt: number;
  record: TeamEvidenceRecord;
  findings: CheckFinding[];
};

export type TeamFlow = {
  stages: Record<TeamStageId, StageState>;
  trace: TraceEntry[];
  /** Stages an agent or gate is working on right now. Empty once the run ends. */
  inFlight: TeamStageId[];
  /** True while the orchestrator is deciding where a failed gate goes back to. */
  routing: boolean;
  /** How many times each agent was handed the work again. */
  returnTrips: Partial<Record<TeamStageId, number>>;
};

const AGENT_CHECK = /^team agent (.+)$/;
const GATE_CHECK = /^team (.+) gate$/;

function isStage(value: string): value is TeamStageId {
  return (TEAM_STAGE_IDS as readonly string[]).includes(value);
}

function asFindings(values: unknown[]): CheckFinding[] {
  return values.filter(
    (value): value is CheckFinding =>
      typeof value === "object" && value !== null && "rule" in value && "severity" in value,
  );
}

/**
 * The runner and the orchestrator each append a record for the same agent pass,
 * differing only in their findings. Collapsing consecutive records that share a
 * `check` leaves one entry per pass while keeping order — so the same stage
 * appearing again later still reads as the return trip it is.
 */
function collapse(records: TeamEvidenceRecord[]): TeamEvidenceRecord[] {
  const collapsed: TeamEvidenceRecord[] = [];
  for (const record of records) {
    const previous = collapsed[collapsed.length - 1];
    if (previous && previous.check === record.check) {
      collapsed[collapsed.length - 1] = { ...previous, ...record };
      continue;
    }
    collapsed.push(record);
  }
  return collapsed;
}

/** The stage(s) the orchestrator dequeues after `stage` clears its gate. */
function successors(stage: TeamStageId, parallel: boolean): TeamStageId[] {
  const index = TEAM_STAGE_IDS.indexOf(stage);
  const next = TEAM_STAGE_IDS[index + 1];
  if (next === undefined) return [];
  if (next === "pcb_layout" && parallel) return [...PARALLEL_PAIR];
  return [next];
}

export function deriveFlow(
  records: TeamEvidenceRecord[],
  runStatus: TeamRunStatus["status"],
  report: TeamRunReport | null,
  parallel: boolean,
): TeamFlow {
  const stages = Object.fromEntries(
    TEAM_STAGE_IDS.map((id) => [
      id,
      { id, phase: "waiting" as StagePhase, attempts: [], unresolvedDetail: null },
    ]),
  ) as Record<TeamStageId, StageState>;
  const trace: TraceEntry[] = [];

  for (const record of collapse(records)) {
    const agentMatch = AGENT_CHECK.exec(record.check);
    const gateMatch = GATE_CHECK.exec(record.check);
    const name = agentMatch?.[1] ?? gateMatch?.[1] ?? "";
    if (!isStage(name)) continue;
    const stage = stages[name];
    const findings = asFindings(record.findings);

    if (agentMatch) {
      stage.attempts.push({ agent: record, gate: null, gateFindings: [] });
      trace.push({ seq: trace.length, stage: name, kind: "agent", attempt: stage.attempts.length, record, findings });
      continue;
    }
    // A gate with no preceding agent record cannot happen through the API, but
    // an attempt is created rather than dropping the gate on the floor.
    if (stage.attempts.length === 0) stage.attempts.push({ agent: null, gate: null, gateFindings: [] });
    const attempt = stage.attempts[stage.attempts.length - 1];
    attempt.gate = record;
    attempt.gateFindings = findings;
    trace.push({ seq: trace.length, stage: name, kind: "gate", attempt: stage.attempts.length, record, findings });
  }

  for (const id of TEAM_STAGE_IDS) {
    const stage = stages[id];
    const last = stage.attempts[stage.attempts.length - 1];
    if (last === undefined) continue;
    if (last.gate === null) {
      stage.phase = "gating";
      continue;
    }
    stage.phase = last.gate.result === "passed" ? "passed" : "failed";
  }

  /**
   * A gate the orchestrator built itself — an agent that returned nothing, an
   * output no tool can ground, a read-only agent that tried to mutate — carries
   * no evidence record, so the stage would sit at "gating" forever. The report
   * lists that finding, so a finished run can say what actually happened.
   */
  const orchestratorFindings = (report?.open_critical_findings ?? []).filter(
    (finding) => finding.rule === "stage grounded and accepted",
  );
  if (runStatus !== "running") {
    for (const id of TEAM_STAGE_IDS) {
      const stage = stages[id];
      if (stage.phase !== "gating") continue;
      const finding = orchestratorFindings.find((item) => item.kicad_object === id);
      stage.phase = finding ? "failed" : "unresolved";
      stage.unresolvedDetail = finding
        ? String(finding.actual)
        : "The run ended before this stage's gate was recorded.";
      if (finding) {
        const last = stage.attempts[stage.attempts.length - 1];
        if (last) last.gateFindings = [finding];
      }
    }
  }

  const lastEntry = trace[trace.length - 1];
  let inFlight: TeamStageId[] = [];
  let routing = false;
  if (runStatus === "running") {
    const gating = TEAM_STAGE_IDS.filter((id) => stages[id].phase === "gating");
    if (gating.length > 0) {
      inFlight = gating;
    } else if (lastEntry === undefined) {
      inFlight = ["project_manager"];
    } else if (lastEntry.kind === "gate" && lastEntry.record.result === "passed") {
      inFlight = successors(lastEntry.stage, parallel);
    } else {
      // A failed gate is routed by the finding text, which only the backend
      // resolves — so no stage is claimed until its own record lands.
      routing = true;
    }
    for (const id of inFlight) {
      if (stages[id].phase === "waiting") stages[id].phase = "running";
    }
  }

  const returnTrips: Partial<Record<TeamStageId, number>> = {};
  for (const id of TEAM_STAGE_IDS) {
    const extra = stages[id].attempts.length - 1;
    if (extra > 0) returnTrips[id] = extra;
  }

  return { stages, trace, inFlight, routing, returnTrips };
}

export const RELEASE_TONE: Record<string, "wire" | "brick" | "copper"> = {
  "ready for engineering review": "wire",
  needs_human_review: "copper",
  failed: "brick",
};

export function releaseLabel(status: string): string {
  if (status === "ready for engineering review") return "Ready for engineering review";
  if (status === "needs_human_review") return "Needs human review";
  if (status === "failed") return "Run failed";
  return status;
}

/** The four states of the single-change flow, derived in page.tsx and only displayed elsewhere. */
export type Stage = "project" | "select" | "preview" | "report";

export type Step = { id: string; label: string };

export const STAGES: { id: Stage; label: string }[] = [
  { id: "project", label: "Project" },
  { id: "select", label: "Describe" },
  { id: "preview", label: "Review" },
  { id: "report", label: "Verdict" },
];

/** The same shape for the ten-agent lane: one brief, one run, one release. */
export type TeamStep = "project" | "brief" | "run" | "release";

export const TEAM_STEPS: { id: TeamStep; label: string }[] = [
  { id: "project", label: "Project" },
  { id: "brief", label: "Brief" },
  { id: "run", label: "Team run" },
  { id: "release", label: "Release" },
];

/** Which lane of the app is in use. Both work on the same project. */
export type Lane = "single" | "team";

import type { Step } from "@/lib/stages";

/**
 * Display-only. The current step is derived from state in page.tsx — this rail
 * reports it and never sets it, so there is one source of truth for where you
 * are. Both lanes use it, so the steps are passed in rather than assumed.
 *
 * Numbered because the flow genuinely is a sequence: nothing can be reviewed
 * before it is planned, and nothing gets a verdict before it runs.
 */
export function StageRail({ steps, current }: { steps: Step[]; current: string }) {
  const index = steps.findIndex((item) => item.id === current);

  return (
    <ol className="flex">
      {steps.map((item, position) => {
        const done = position < index;
        const active = position === index;
        return (
          <li
            key={item.id}
            className="relative flex min-w-0 flex-1 flex-col items-center pt-0.5"
            aria-current={active ? "step" : undefined}
          >
            {position > 0 && (
              <span
                aria-hidden
                className={`absolute left-0 top-[6px] h-[1.5px] w-1/2 ${done || active ? "bg-wire" : "bg-rule"}`}
              />
            )}
            {position < steps.length - 1 && (
              <span
                aria-hidden
                className={`absolute right-0 top-[6px] h-[1.5px] w-1/2 ${done ? "bg-wire" : "bg-rule"}`}
              />
            )}
            <span
              aria-hidden
              className={`relative z-10 h-[13px] w-[13px] rounded-full border-[3px] ${
                done
                  ? "border-wire bg-wire"
                  : active
                    ? "border-wire bg-paper"
                    : "border-rule bg-paper"
              }`}
            />
            <span
              className={`mt-2 min-w-0 text-center font-mono text-[0.625rem] uppercase leading-tight tracking-[0.1em] ${
                active ? "font-semibold text-wire" : "text-muted"
              }`}
            >
              {item.label}
            </span>
          </li>
        );
      })}
    </ol>
  );
}

"use client";

import { HealthResponse, SessionResponse } from "@/lib/api";
import { TEAM_AGENTS } from "@/lib/team";
import { Chip, Notice, Panel, Segmented } from "./ui";

/**
 * The brief handed to the team. One prose request, and the choice of who
 * actually does the thinking — which is the only decision here that costs
 * money, so it is stated in full next to the button rather than buried.
 */
export function TeamBrief({
  session,
  health,
  request,
  runner,
  busy,
  onRequest,
  onRunner,
  onStart,
}: {
  session: SessionResponse;
  health: HealthResponse | null;
  request: string;
  runner: "devin" | "stub";
  busy: boolean;
  onRequest: (next: string) => void;
  onRunner: (next: "devin" | "stub") => void;
  onStart: () => void;
}) {
  const live = runner === "devin";
  const stages = TEAM_AGENTS.length;

  return (
    <Panel
      eyebrow="Step 01"
      title="Brief the team"
      aside={<Chip>{stages} agents</Chip>}
    >
      <p className="min-w-0 wrap-any text-[0.8125rem] leading-snug text-muted">
        One request, worked through {stages} stages in a fixed order. Every stage&apos;s output is checked by a
        deterministic tool before the next one starts, and a failed check sends the work back to whichever agent
        is responsible.
      </p>

      <label className="mt-4 block">
        <span className="eyebrow">What should the board do</span>
        <textarea
          className="field mt-2 min-h-[5.5rem] resize-y font-sans leading-snug"
          value={request}
          disabled={busy}
          onChange={(event) => onRequest(event.target.value)}
          placeholder="Monitor temperature over I2C on a USB-C powered ESP32 board."
        />
      </label>

      <div className="mt-4 flex flex-wrap items-end justify-between gap-x-4 gap-y-3 border-t border-rule pt-4">
        <div className="min-w-0">
          <span className="eyebrow">Who runs the agents</span>
          <div className="mt-2">
            <Segmented
              label="Team runner"
              value={runner}
              onChange={onRunner}
              disabled={busy}
              options={[
                { value: "stub", label: "Stub" },
                { value: "devin", label: "Devin" },
              ]}
            />
          </div>
        </div>
        <dl className="min-w-0 text-right">
          <dt className="eyebrow">Manufacturer profile</dt>
          <dd className="mt-1 min-w-0 wrap-any font-mono text-[0.75rem] text-ink">generic_two_layer</dd>
        </dl>
      </div>

      <div className="mt-3">
        {live ? (
          <Notice tone="copper" title="This spends real Devin sessions">
            Each stage opens its own Devin session against the key in <span className="font-mono">.env</span>, capped
            at {" "}3 ACU apiece, so a full pass is up to {stages} sessions. Expect minutes, not seconds.
            {health?.team_runner === "devin" && " This is also the backend's own default."}
          </Notice>
        ) : (
          <Notice tone="neutral" title="Offline and free">
            The stub runner is deterministic and opens no sessions. It is a wiring test, not a demo: its agents
            return near-empty output, so the architecture gate fails and the run ends at{" "}
            <span className="font-mono">needs_human_review</span> after two return trips. That path is worth
            watching — it is exactly what a real failure looks like.
          </Notice>
        )}
      </div>

      <div className="mt-5 flex flex-wrap items-center gap-2 border-t border-rule pt-4">
        <button type="button" className="btn" disabled={busy || request.trim().length === 0} onClick={onStart}>
          {busy ? "Starting…" : `Start the ${stages}-agent run`}
        </button>
        <p className="min-w-0 wrap-any text-[0.75rem] leading-snug text-muted">
          Runs on a fresh copy of <span className="font-mono">{session.project}</span>. Nothing touches the
          project you opened.
        </p>
      </div>
    </Panel>
  );
}

"use client";

import {
  AGENT_BY_ID,
  PARALLEL_PAIR,
  StagePhase,
  TEAM_STAGE_IDS,
  TeamFlow,
  TeamStageId,
} from "@/lib/team";
import { Chip, Panel } from "./ui";

/**
 * The run, drawn as it actually executes: ten agents in a fixed order, each one
 * followed by the deterministic gate that has to accept its output before the
 * next agent starts. Layout and simulation are drawn as a fork because the
 * backend really does run them at the same time.
 *
 * Everything here is read out of the evidence the orchestrator appends as it
 * goes. A stage with no records yet says so.
 */

const PHASE: Record<StagePhase, { label: string; tone: "neutral" | "wire" | "brick" | "copper" }> = {
  waiting: { label: "waiting", tone: "neutral" },
  running: { label: "working", tone: "copper" },
  gating: { label: "at the gate", tone: "copper" },
  passed: { label: "accepted", tone: "wire" },
  failed: { label: "sent back", tone: "brick" },
  unresolved: { label: "no gate recorded", tone: "copper" },
};

export function TeamFlowRail({
  flow,
  status,
  parallel,
  selected,
  onSelect,
}: {
  flow: TeamFlow;
  status: "running" | "completed" | "failed";
  parallel: boolean;
  selected: TeamStageId | null;
  onSelect: (stage: TeamStageId) => void;
}) {
  const sequence = TEAM_STAGE_IDS.filter((id) => !PARALLEL_PAIR.includes(id));
  const done = TEAM_STAGE_IDS.filter((id) => flow.stages[id].phase === "passed").length;
  const trips = Object.values(flow.returnTrips).reduce((total, count) => total + (count ?? 0), 0);

  return (
    <Panel
      eyebrow="Step 02"
      title="The run, stage by stage"
      aside={
        <div className="flex flex-wrap items-center justify-end gap-1.5">
          <Chip tone={done === TEAM_STAGE_IDS.length ? "wire" : "neutral"}>
            {done}/{TEAM_STAGE_IDS.length} gates passed
          </Chip>
          {trips > 0 && (
            <Chip tone="brick">
              {trips} return {trips === 1 ? "trip" : "trips"}
            </Chip>
          )}
        </div>
      }
    >
      <ol className="min-w-0">
        {sequence.map((id, index) => {
          const forkHere = parallel && TEAM_STAGE_IDS[TEAM_STAGE_IDS.indexOf(id) + 1] === "pcb_layout";
          return (
            <li key={id} className="min-w-0">
              <StageRow
                stage={id}
                number={TEAM_STAGE_IDS.indexOf(id) + 1}
                flow={flow}
                selected={selected === id}
                onSelect={onSelect}
                lastOfBranch={false}
              />
              {forkHere && (
                <ParallelGroup flow={flow} selected={selected} onSelect={onSelect} parallel={parallel} />
              )}
            </li>
          );
        })}
        {!parallel &&
          PARALLEL_PAIR.map((id) => (
            <li key={id} className="min-w-0">
              <StageRow
                stage={id}
                number={TEAM_STAGE_IDS.indexOf(id) + 1}
                flow={flow}
                selected={selected === id}
                onSelect={onSelect}
                lastOfBranch={false}
              />
            </li>
          ))}
      </ol>

      {flow.routing && (
        <p className="mt-3 min-w-0 wrap-any border-t border-rule pt-3 text-[0.75rem] leading-snug text-copper">
          A gate rejected its stage. The orchestrator is picking which agent owns the fix from the finding
          itself — every stage after that one is replayed once it lands.
        </p>
      )}

      {status === "running" && !flow.routing && flow.inFlight.length === 0 && (
        <p className="mt-3 min-w-0 wrap-any border-t border-rule pt-3 text-[0.75rem] leading-snug text-muted">
          Waiting on the first agent to report.
        </p>
      )}

      <p className="mt-3 min-w-0 wrap-any border-t border-rule pt-3 text-[0.75rem] leading-snug text-muted">
        Agents only propose. Each gate is a deterministic check — the schematic and layout gates are KiCAD&apos;s
        own ERC and DRC — and a rejected stage is rolled back from a checkpoint before the work is handed on.
      </p>
    </Panel>
  );
}

/** Layout and simulation, drawn as the concurrent pair the backend runs. */
function ParallelGroup({
  flow,
  selected,
  parallel,
  onSelect,
}: {
  flow: TeamFlow;
  selected: TeamStageId | null;
  parallel: boolean;
  onSelect: (stage: TeamStageId) => void;
}) {
  if (!parallel) return null;
  return (
    <div className="relative min-w-0 pl-[1.5625rem]">
      {/* The trunk continues behind the fork so the two branches read as one step. */}
      <span aria-hidden className="absolute left-[0.375rem] top-0 h-full w-[1.5px] bg-rule" />
      <div className="min-w-0 border-l-[1.5px] border-dashed border-wire/50 pl-3">
        <p className="eyebrow py-2">Concurrent — one step, two agents</p>
        <div className="min-w-0 divide-y divide-rule/60 border-y border-rule/60">
          {PARALLEL_PAIR.map((id) => (
            <StageRow
              key={id}
              stage={id}
              number={TEAM_STAGE_IDS.indexOf(id) + 1}
              flow={flow}
              selected={selected === id}
              onSelect={onSelect}
              lastOfBranch
            />
          ))}
        </div>
      </div>
    </div>
  );
}

function StageRow({
  stage,
  number,
  flow,
  selected,
  lastOfBranch,
  onSelect,
}: {
  stage: TeamStageId;
  number: number;
  flow: TeamFlow;
  selected: boolean;
  /** Inside the fork the trunk is drawn by the group, not the row. */
  lastOfBranch: boolean;
  onSelect: (stage: TeamStageId) => void;
}) {
  const agent = AGENT_BY_ID[stage];
  const state = flow.stages[stage];
  const phase = PHASE[state.phase];
  const attempt = state.attempts[state.attempts.length - 1];
  const trips = flow.returnTrips[stage] ?? 0;
  const errors = attempt?.gateFindings.filter((finding) => finding.severity === "error").length ?? 0;
  const gateResult = attempt?.gate?.result ?? null;
  const live = flow.inFlight.includes(stage);
  const last = number === TEAM_STAGE_IDS.length;

  return (
    <button
      type="button"
      onClick={() => onSelect(stage)}
      aria-pressed={selected}
      className={`relative flex w-full min-w-0 items-start gap-3 py-2.5 text-left transition-colors ${
        selected ? "bg-wire-soft/60" : "hover:bg-paper/70"
      }`}
    >
      {/* The wire down the gutter: teal behind stages the run has cleared. */}
      {!lastOfBranch && !last && (
        <span
          aria-hidden
          className={`absolute left-[0.375rem] top-[1.125rem] h-full w-[1.5px] ${
            state.phase === "passed" ? "bg-wire" : "bg-rule"
          }`}
        />
      )}

      <span className="relative z-10 mt-[0.3125rem] shrink-0">
        <FlowNode phase={state.phase} live={live} />
      </span>

      <span className="min-w-0 flex-1">
        <span className="flex flex-wrap items-baseline gap-x-2 gap-y-1">
          <span className="font-mono text-[0.6875rem] text-muted">
            {String(number).padStart(2, "0")}
          </span>
          <span className="min-w-0 wrap-any text-[0.875rem] font-semibold leading-tight tracking-[-0.012em] text-ink">
            {agent.name}
          </span>
          {agent.mutates && (
            <span className="chip border-copper-line/45 bg-copper-soft !py-0 text-copper">writes files</span>
          )}
          {trips > 0 && (
            <span className="chip border-brick/35 bg-brick-soft !py-0 text-brick">
              attempt {state.attempts.length}
            </span>
          )}
        </span>

        <span className="mt-1 block min-w-0 wrap-any text-[0.75rem] leading-snug text-muted">
          {agent.produces}
        </span>

        {/* agent → gate → verdict, spelled out on one line. */}
        <span className="mt-1.5 flex flex-wrap items-center gap-x-2 gap-y-1 font-mono text-[0.6875rem] leading-none">
          <span className={`${phase.tone === "wire" ? "text-wire" : phase.tone === "brick" ? "text-brick" : phase.tone === "copper" ? "text-copper" : "text-muted"}`}>
            {phase.label}
          </span>
          <span aria-hidden className="text-rule">
            →
          </span>
          <span className="min-w-0 wrap-any text-muted">gate: {agent.gate}</span>
          {gateResult && (
            <span className={gateResult === "passed" ? "text-wire" : "text-brick"}>· {gateResult}</span>
          )}
          {errors > 0 && (
            <span className="text-brick">
              · {errors} {errors === 1 ? "finding" : "findings"}
            </span>
          )}
        </span>
      </span>
    </button>
  );
}

/** A solder junction on the wire: hollow until the stage has cleared its gate. */
function FlowNode({ phase, live }: { phase: StagePhase; live: boolean }) {
  const base = "block h-[13px] w-[13px] rounded-full border-[3px]";
  if (phase === "passed") return <span aria-hidden className={`${base} border-wire bg-wire`} />;
  if (phase === "failed") return <span aria-hidden className={`${base} border-brick bg-brick`} />;
  if (phase === "gating" || phase === "unresolved")
    return <span aria-hidden className={`${base} border-copper-line bg-copper-soft`} />;
  if (phase === "running" || live)
    return (
      <span aria-hidden className={`${base} animate-pulse border-copper-line bg-paper`} />
    );
  return <span aria-hidden className={`${base} border-rule bg-paper`} />;
}

"use client";

import type { ReactNode } from "react";
import {
  AGENT_BY_ID,
  CheckFinding,
  StageAttempt,
  TeamRunReport,
  TeamStageId,
  TeamFlow,
} from "@/lib/team";
import { Bullets, Chip, DataCell, Notice, Panel } from "./ui";

/**
 * One stage, opened up: what it was given, who ran it, what it proposed, and
 * what the gate made of that. The output renderers below are per stage because
 * each agent has its own typed output model — showing a requirements document
 * and a layout proposal through the same generic viewer would hide exactly the
 * detail worth reading.
 */
export function TeamStageDetail({
  stage,
  flow,
  report,
  onClose,
}: {
  stage: TeamStageId;
  flow: TeamFlow;
  report: TeamRunReport | null;
  onClose: () => void;
}) {
  const agent = AGENT_BY_ID[stage];
  const state = flow.stages[stage];
  const attempt: StageAttempt | undefined = state.attempts[state.attempts.length - 1];
  const result = report?.per_stage_results?.[stage];
  const output = result?.output ?? null;

  return (
    <Panel
      eyebrow={`Agent ${String(Object.keys(AGENT_BY_ID).indexOf(stage) + 1).padStart(2, "0")}`}
      title={agent.name}
      aside={
        <button type="button" className="btn-ghost shrink-0 !px-2.5 !py-1 !text-[0.75rem]" onClick={onClose}>
          Close
        </button>
      }
    >
      <p className="min-w-0 wrap-any text-[0.8125rem] leading-snug text-muted">
        {agent.role}. {agent.produces}.
      </p>

      <dl className="mt-4 grid grid-cols-2 gap-x-4 gap-y-3 border-y border-rule py-3 sm:grid-cols-4">
        <DataCell label="Output model" value={agent.outputModel} />
        <DataCell label="Grounded by" value={agent.gate} />
        <DataCell label="Design files" value={agent.mutates ? "may write" : "read-only"} />
        <DataCell label="Passes" value={String(state.attempts.length)} />
      </dl>

      <section className="mt-4">
        <h3 className="eyebrow">Given to it</h3>
        <div className="mt-2 flex min-w-0 flex-wrap gap-1.5">
          {agent.reads.length === 0 && <Chip>the request and the project itself</Chip>}
          {agent.reads.map((source) => (
            <Chip key={source} tone="wire">
              {AGENT_BY_ID[source].name}
            </Chip>
          ))}
        </div>
        <p className="mt-2 min-w-0 wrap-any text-[0.75rem] leading-snug text-muted">
          Only these outputs are passed on — the registry declares each agent&apos;s inputs, so a later stage
          cannot quietly read something it was not given.
        </p>
      </section>

      {attempt?.agent && (
        <section className="mt-4 border-t border-rule pt-4">
          <h3 className="eyebrow">The session</h3>
          <dl className="mt-2 grid grid-cols-2 gap-x-4 gap-y-3 sm:grid-cols-4">
            <DataCell label="Runner" value={result?.runner ?? attempt.agent.runner ?? "unknown"} />
            <DataCell label="Status" value={result?.status ?? attempt.agent.result} />
            <DataCell
              label="ACUs"
              value={(result?.acus_consumed ?? attempt.agent.acus_consumed).toFixed(2)}
            />
            <DataCell
              label="Took"
              value={`${(result?.duration_seconds ?? attempt.agent.duration_seconds).toFixed(1)} s`}
            />
          </dl>
          {(result?.session_url ?? attempt.agent.session_url) && (
            <p className="mt-2 min-w-0 wrap-any font-mono text-[0.6875rem] leading-snug text-muted">
              {renderSessionUrl(result?.session_url ?? attempt.agent.session_url)}
            </p>
          )}
          {result?.unresolved_questions?.length ? (
            <Bullets title="Questions it could not settle" items={result.unresolved_questions} tone="copper" />
          ) : null}
        </section>
      )}

      <section className="mt-4 border-t border-rule pt-4">
        <h3 className="eyebrow">The gate</h3>
        {attempt?.gate ? (
          <>
            <p className="mt-2 flex flex-wrap items-center gap-x-2 gap-y-1 font-mono text-[0.75rem] leading-none">
              <span className="text-muted">{attempt.gate.tool}</span>
              <span aria-hidden className="text-rule">
                →
              </span>
              <span className={attempt.gate.result === "passed" ? "text-wire" : "text-brick"}>
                {attempt.gate.result}
              </span>
            </p>
            <FindingsTable findings={attempt.gateFindings} />
          </>
        ) : state.unresolvedDetail ? (
          <div className="mt-2">
            <Notice tone={state.phase === "failed" ? "brick" : "copper"} title="Built by the orchestrator">
              {state.unresolvedDetail}
            </Notice>
          </div>
        ) : (
          <p className="mt-2 min-w-0 wrap-any text-[0.8125rem] leading-snug text-muted">
            {state.attempts.length === 0
              ? "This stage has not run yet."
              : "The agent has reported; its gate is still running."}
          </p>
        )}
      </section>

      {output !== null && output !== undefined && (
        <section className="mt-4 border-t border-rule pt-4">
          <h3 className="eyebrow">What it proposed</h3>
          <div className="mt-2 min-w-0">
            <StageOutput stage={stage} output={output} />
          </div>
        </section>
      )}
    </Panel>
  );
}

/** Devin sessions are real links; the stub's `stub://` marker is not. */
function renderSessionUrl(url: string | null | undefined): ReactNode {
  if (!url) return null;
  if (url.startsWith("http")) {
    return (
      <a href={url} target="_blank" rel="noreferrer" className="text-wire underline">
        {url}
      </a>
    );
  }
  return url;
}

function FindingsTable({ findings }: { findings: CheckFinding[] }) {
  if (findings.length === 0) {
    return (
      <p className="mt-2 min-w-0 wrap-any text-[0.75rem] leading-snug text-muted">
        Nothing to report — the check found no findings at all.
      </p>
    );
  }
  const tone = (severity: string) =>
    severity === "error" ? "text-brick" : severity === "warning" ? "text-copper" : "text-muted";

  return (
    <ul className="mt-2 divide-y divide-rule/60 border-y border-rule/60">
      {findings.map((finding, index) => (
        <li key={`${finding.rule}-${index}`} className="min-w-0 py-2">
          <p className="flex flex-wrap items-baseline gap-x-2">
            <span className={`font-mono text-[0.6875rem] uppercase tracking-[0.08em] ${tone(finding.severity)}`}>
              {finding.severity}
            </span>
            <span className="min-w-0 wrap-any text-[0.8125rem] font-medium leading-snug text-ink">
              {finding.rule}
            </span>
          </p>
          <dl className="mt-1.5 grid grid-cols-1 gap-x-4 gap-y-1 sm:grid-cols-2">
            <Pair label="found" value={format(finding.actual)} />
            <Pair label="expected" value={format(finding.expected)} />
            <Pair label="object" value={finding.kicad_object} />
            <Pair label="source" value={finding.evidence_source} />
          </dl>
        </li>
      ))}
    </ul>
  );
}

function Pair({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex min-w-0 gap-2">
      <dt className="eyebrow shrink-0 pt-[0.15rem]">{label}</dt>
      <dd className="min-w-0 wrap-any font-mono text-[0.75rem] leading-snug text-ink">{value}</dd>
    </div>
  );
}

function format(value: unknown): string {
  if (value === null || value === undefined) return "—";
  if (typeof value === "string") return value || "—";
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  return JSON.stringify(value);
}

/* ------------------------------ stage outputs ----------------------------- */

type Row = Record<string, unknown>;

function asRows(value: unknown): Row[] {
  return Array.isArray(value) ? (value.filter((item) => typeof item === "object" && item !== null) as Row[]) : [];
}

function asObject(value: unknown): Row {
  return typeof value === "object" && value !== null ? (value as Row) : {};
}

function asStrings(value: unknown): string[] {
  return Array.isArray(value) ? value.map((item) => (typeof item === "string" ? item : format(item))) : [];
}

/** Compact table for a list of typed records. Columns are named, never guessed. */
function MiniTable({
  columns,
  rows,
  empty,
}: {
  columns: { key: string; label: string; render?: (row: Row) => ReactNode }[];
  rows: Row[];
  empty: string;
}) {
  if (rows.length === 0) {
    return <p className="min-w-0 wrap-any text-[0.8125rem] leading-snug text-muted">{empty}</p>;
  }
  return (
    <div className="overflow-x-auto">
      <table className="w-full border-collapse text-left">
        <thead>
          <tr>
            {columns.map((column) => (
              <th key={column.key} scope="col" className="eyebrow border-b border-rule pb-1.5 pr-3 font-medium">
                {column.label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, index) => (
            <tr key={index}>
              {columns.map((column) => (
                <td
                  key={column.key}
                  className="min-w-0 border-b border-rule/60 py-2 pr-3 align-top font-mono text-[0.75rem] leading-snug text-ink [overflow-wrap:anywhere]"
                >
                  {column.render ? column.render(row) : format(row[column.key])}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function Facts({ items }: { items: { label: string; value: string }[] }) {
  return (
    <dl className="grid grid-cols-2 gap-x-4 gap-y-3 sm:grid-cols-3">
      {items.map((item) => (
        <DataCell key={item.label} label={item.label} value={item.value} />
      ))}
    </dl>
  );
}

function StageOutput({ stage, output }: { stage: TeamStageId; output: unknown }) {
  const data = asObject(output);

  switch (stage) {
    case "project_manager":
      return (
        <div className="space-y-3">
          <p className="min-w-0 wrap-any text-[0.875rem] font-medium leading-snug text-ink">
            {format(data.project_goal)}
          </p>
          <div>
            <h4 className="eyebrow">Stage order it proposed</h4>
            <div className="mt-1.5 flex min-w-0 flex-wrap gap-1.5">
              {asStrings(data.workflow).length === 0 && <Chip>none — the canonical order is used</Chip>}
              {asStrings(data.workflow).map((item, index) => (
                <Chip key={`${item}-${index}`} tone="wire">
                  {index + 1}. {item}
                </Chip>
              ))}
            </div>
          </div>
          <Facts items={[{ label: "Status", value: format(data.status) }]} />
        </div>
      );

    case "requirements": {
      const power = asObject(data.power);
      const mechanical = asObject(data.mechanical);
      return (
        <div className="space-y-4">
          <MiniTable
            rows={asRows(data.requirements)}
            empty="No requirements were produced."
            columns={[
              { key: "id", label: "ID" },
              { key: "statement", label: "Statement" },
              {
                key: "value",
                label: "Value",
                render: (row) => `${format(row.value)}${row.unit ? ` ${row.unit}` : ""}`,
              },
              { key: "category", label: "Category" },
              { key: "source", label: "Source" },
            ]}
          />
          <Facts
            items={[
              { label: "Input", value: format(power.input) },
              { label: "Logic", value: format(power.logic_voltage) },
              { label: "Max current", value: format(power.maximum_current_ma) },
              { label: "Max width", value: format(mechanical.maximum_width_mm) },
              { label: "Max height", value: format(mechanical.maximum_height_mm) },
              { label: "Layers", value: format(mechanical.layers) },
            ]}
          />
          <MiniTable
            rows={asRows(data.interfaces)}
            empty="No interfaces were named."
            columns={[
              { key: "type", label: "Interface" },
              { key: "voltage", label: "Voltage" },
              { key: "devices", label: "Devices" },
            ]}
          />
          <Bullets title="Constraints" items={asStrings(data.constraints)} />
          <Bullets title="Acceptance tests" items={asStrings(data.acceptance_tests)} tone="wire" />
        </div>
      );
    }

    case "architecture":
      return (
        <div className="space-y-4">
          <MiniTable
            rows={asRows(data.blocks)}
            empty="No functional blocks were produced — which is what the architecture gate rejects."
            columns={[
              { key: "id", label: "Block" },
              { key: "type", label: "Type" },
              {
                key: "requirement_ids",
                label: "Serves",
                render: (row) => asStrings(row.requirement_ids).join(", ") || "—",
              },
              {
                key: "power",
                label: "Power",
                render: (row) =>
                  row.power_required_ma || row.power_available_ma
                    ? `${format(row.power_required_ma)} / ${format(row.power_available_ma)} mA`
                    : "—",
              },
            ]}
          />
          <MiniTable
            rows={asRows(data.connections)}
            empty="No block connections were produced."
            columns={[
              { key: "from", label: "From" },
              { key: "to", label: "To" },
              { key: "signal", label: "Signal" },
            ]}
          />
          <Bullets title="Open questions" items={asStrings(data.unresolved_questions)} tone="copper" />
        </div>
      );

    case "components":
      return (
        <div className="space-y-3">
          <MiniTable
            rows={asRows(data.components)}
            empty="No parts were selected."
            columns={[
              { key: "reference_group", label: "Group" },
              { key: "manufacturer_part", label: "Part" },
              { key: "quantity", label: "Qty" },
              { key: "symbol", label: "Symbol" },
              { key: "footprint", label: "Footprint" },
            ]}
          />
          {asRows(data.components).map((component, index) => (
            <div key={index} className="min-w-0 border-t border-rule/60 pt-2">
              <p className="min-w-0 wrap-any text-[0.8125rem] leading-snug text-ink">
                <span className="font-mono text-[0.75rem] text-muted">{format(component.reference_group)} — </span>
                {format(component.reason)}
              </p>
              <Bullets title="Checked against" items={asStrings(component.verified_constraints)} tone="wire" />
            </div>
          ))}
        </div>
      );

    case "schematic_design":
      return (
        <div className="space-y-4">
          <Facts
            items={[
              { label: "Protocol", value: format(data.protocol) },
              { label: "Logic", value: format(data.logic_voltage) },
              { label: "Pull-up", value: format(data.pullup_value) },
            ]}
          />
          <MiniTable
            rows={asRows(data.intents)}
            empty="No connection intents were produced."
            columns[
              // placeholder replaced below
            ]
