import { chromium } from "/Users/chiragnvijay/.npm/_npx/e41f203b7505f1fb/node_modules/playwright/index.mjs";
import { readFileSync } from "node:fs";

const OUT = process.argv[2];
const report = JSON.parse(readFileSync(`${OUT}/full-report.json`, "utf8"));
const records = readFileSync(`${OUT}/full-evidence.jsonl`, "utf8")
  .split("\n").filter(Boolean).map((line) => JSON.parse(line));
const events = readFileSync(`${OUT}/full-events.jsonl`, "utf8")
