function describeIntent(row: Row): string {
  switch (row.type) {
    case "connect_pins":
      return `${edge(row, "from")} ↔ ${edge(row, "to")} as ${format(row.net_name)}`;
    case "connect_pin_to_net":
      return `${format(row.pin)} → ${format(row.net)}`;
    case "ensure_pullup":
